using System.Net;
using System.Net.Http.Json;
using CondoManager.Application;
using CondoManager.Domain;
using CondoManager.Infrastructure;
using Microsoft.EntityFrameworkCore;
using Npgsql;
namespace CondoManager.IntegrationTests;
[Collection("PostgreSQL")]
public class ResidentFinanceTests
{
    private sealed record Context(Guid? TenantId) : ICurrentTenant {public Guid? UserId=>TenantId;public StudioRole? Role=>StudioRole.StudioAdmin;}
    private static AppDbContext Db(Guid? t=null)=>new(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql(Environment.GetEnvironmentVariable("CONDOMANAGER_TEST_POSTGRES")).Options,new Context(t));
    private static async Task<T> Send<T>(HttpClient c,string path,object input) {using var r=await c.PostAsJsonAsync(path,input,SecurityTestHost.Json);Assert.True(r.IsSuccessStatusCode,$"{path}: {r.StatusCode}: {await r.Content.ReadAsStringAsync()}");return (await r.Content.ReadFromJsonAsync<T>(SecurityTestHost.Json))!;}
    private static async Task<HttpStatusCode> Status(HttpClient c,string path,object input){using var r=await c.PostAsJsonAsync(path,input,SecurityTestHost.Json);return r.StatusCode;}
    private static async Task<T> Get<T>(HttpClient c,string path)=>(await c.GetFromJsonAsync<T>(path,SecurityTestHost.Json))!;
    internal sealed record Fixture(BudgetApiTests.Fixture Base,Guid Budget,Guid[] Units,Guid[] People,Guid Financial) : IAsyncDisposable
    {
        public HttpClient C=>Base.Client;public string Path=>"/api/resident-finance/condominiums/"+Base.Condo;
        public PlanInput Input(params decimal[] weights)=>new(Budget,new(2026,1,1),ScheduleMode.Percentages,weights.Select((w,i)=>new InstallmentSchedule(new(2026,i*2+2,1),w)).ToArray(),Units.Select((u,i)=>new DebtorSelection(u,People[i],1)).ToArray(),Guid.NewGuid());
        public ResidentReceiptInput Receipt(decimal amount,Guid? debtor=null,Guid? payer=null,bool recordOnly=false,Guid? existing=null)=>new(Guid.NewGuid(),Base.Period,Financial,new(2026,8,1),amount,"Synthetic receipt",debtor,payer,recordOnly,existing);
        public AllocateReceiptInput Allocate(params (Guid Id,decimal Amount)[] items)=>new(Guid.NewGuid(),Base.Period,new(2026,8,1),items.Select(a=>new ReceiptAllocationInput(a.Id,a.Amount)).ToArray());
        public async ValueTask DisposeAsync()=>await Base.DisposeAsync();
    }
    internal static async Task<Fixture> Setup(decimal budgetAmount=12000)
    {
        var f=await BudgetApiTests.Setup();var c=f.Client;await using var db=Db(f.Tenant);var units=await db.PropertyUnits.Where(u=>u.CondominiumId==f.Condo).OrderBy(u=>u.Code).Select(u=>u.Id).ToArrayAsync();var people=new List<Guid>();
        for(var i=0;i<units.Length;i++){var p=await Send<PersonDto>(c,"/api/people",new PersonInput("P"+i,PersonKind.NaturalPerson,"Synthetic","Person "+i,"SYNTHETIC"+i,null,null,null,null,null));people.Add(p.Id);await Send<AssociationDto>(c,$"/api/condominiums/{f.Condo}/units/{units[i]}/associations",new AssociationInput(p.Id,UnitPersonRole.Owner,new(2026,1,1),null,1));}
        var tablePath=$"/api/condominiums/{f.Condo}/allocation-tables";var table=await Send<AllocationTableDto>(c,tablePath,new AllocationTableInput("T","Synthetic table",1000,new(2026,1,1)));
        for(var i=0;i<units.Length;i++){using var r=await c.PutAsJsonAsync(tablePath+$"/{table.Id}/entries/{units[i]}",new AllocationEntryInput(new decimal[]{500,300,200}[i]),SecurityTestHost.Json);r.EnsureSuccessStatusCode();}await Send<AllocationTableDto>(c,tablePath+$"/{table.Id}/activate",new{});
        var rulePath=$"/api/allocations/condominiums/{f.Condo}/rules";var rule=await Send<RuleDto>(c,rulePath,new RuleInput("Synthetic millesimal",null,AllocationCriterion.Millesimal,[new(AllocationCriterion.Millesimal,100,table.Id,null,null,null)]));await Send<RuleDto>(c,rulePath+$"/{rule.Id}/activate",new{});
        var budget=await Send<BudgetDto>(c,f.Base,f.Input() with{Lines=[new(f.Account,"Synthetic budget expense",budgetAmount,rule.Id)]});await Send<BudgetDto>(c,f.Base+$"/{budget.Id}/propose",new{});var preview=await Send<BudgetPreviewDto>(c,f.Base+$"/{budget.Id}/preview",new{});await Send<BudgetDto>(c,f.Base+$"/{budget.Id}/approve",new BudgetApprovalInput(preview.Hash));
        var bank=await Send<FinancialAccountDto>(c,$"/api/accounting/condominiums/{f.Condo}/financial-accounts",new FinancialAccountInput("BANK","Synthetic bank",FinancialAccountType.BankAccount,null,0,f.Period,new(2026,1,1),Guid.NewGuid()));return new(f,budget.Id,units,people.ToArray(),bank.Id);
    }
    internal static async Task<PlanDto> Issue(Fixture f,PlanInput? input=null)
    {var plan=await Send<PlanDto>(f.C,f.Path+"/plans",input??f.Input(25,25,25,25));return await Send<PlanDto>(f.C,f.Path+$"/plans/{plan.Id}/approve",new PlanApproval(Guid.NewGuid(),new(2026,1,1),plan.Snapshot.Hash));}
    [PostgresFact] public async Task ReferenceAPlanPreviewDraftApprovalAndLedgerAreExactlyReconciled()
    {
        await using var f=await Setup();var input=f.Input(25,25,25,25);var preview=await Send<PlanPreview>(f.C,f.Path+"/plans/preview",input);Assert.Equal(12000,preview.Total);Assert.Equal(new decimal[]{6000,3600,2400},f.Units.Select(u=>preview.Quotas.Where(q=>q.PropertyUnitId==u).Sum(q=>q.Amount)));
        foreach(var g in preview.Installments.GroupBy(i=>i.Position))Assert.Equal(3000,g.Sum(i=>i.Amount));var p=await Send<PlanDto>(f.C,f.Path+"/plans",input);Assert.Equal(p.Id,(await Send<PlanDto>(f.C,f.Path+"/plans",input)).Id);Assert.Empty(await Get<CreditDto[]>(f.C,f.Path+"/credits"));
        var approval=new PlanApproval(Guid.NewGuid(),new(2026,1,1),p.Snapshot.Hash);var issued=await Send<PlanDto>(f.C,f.Path+$"/plans/{p.Id}/approve",approval);Assert.Equal(issued.JournalEntryId,(await Send<PlanDto>(f.C,f.Path+$"/plans/{p.Id}/approve",approval)).JournalEntryId);
        var credits=await Get<CreditDto[]>(f.C,f.Path+"/credits");Assert.Equal(12,credits.Length);Assert.Equal(12000,credits.Sum(c=>c.Amount));await using var db=Db(f.Base.Tenant);var journal=await db.JournalEntries.Include(j=>j.Lines).SingleAsync(j=>j.Id==issued.JournalEntryId);Assert.Equal(JournalKind.Assessment,journal.Kind);Assert.Equal(12000,journal.Lines.Sum(l=>l.Debit));Assert.Equal(journal.Lines.Sum(l=>l.Debit),journal.Lines.Sum(l=>l.Credit));Assert.Empty(await db.ExpenseDocuments.ToListAsync());
        await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"Installments\" SET \"Amount\"={1m} WHERE \"PlanId\"={issued.Id}"));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,$"/api/accounting/condominiums/{f.Base.Condo}/journals/{journal.Id}/reverse",new ReversalInput(Guid.NewGuid(),f.Base.Period,new(2026,8,1),"Invalid direct reversal")));
    }
    [PostgresFact] public async Task PartialMultipleAndFullPaymentsKeepPayerDistinctAndPreventOverpayment()
    {
        await using var f=await Setup(4000);await Issue(f);var credit=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).First(c=>c.PropertyUnitId==f.Units[0]);var r=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(200,f.People[0],f.People[1]));var command=f.Allocate((credit.Id,200));await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{r.Id}/allocate",command);await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{r.Id}/allocate",command);
        credit=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).Single(c=>c.Id==credit.Id);Assert.Equal(200,credit.Paid);Assert.Equal(300,credit.Residual);Assert.Equal("PartiallyPaid",credit.Status);Assert.NotEqual(r.DebtorId,r.PayerId);
        var r2=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(400));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/receipts/{r2.Id}/allocate",f.Allocate((credit.Id,300.01m))));await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{r2.Id}/allocate",f.Allocate((credit.Id,300)));credit=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).Single(c=>c.Id==credit.Id);Assert.Equal(0,credit.Residual);Assert.Equal("Paid",credit.Status);Assert.Equal(100,(await Get<ResidentReceiptDto[]>(f.C,f.Path+"/receipts")).Single(x=>x.Id==r2.Id).Unallocated);
    }
    [PostgresFact] public async Task OneReceiptAcrossRatesUnallocatedExcessAndReceiptIdempotence()
    {
        await using var f=await Setup();await Issue(f);var rates=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).Where(c=>c.PropertyUnitId==f.Units[0]).Take(2).ToArray();var input=f.Receipt(700);var r=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",input);Assert.Equal(r.Id,(await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",input)).Id);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+"/receipts",input with{Amount=701}));
        Assert.Equal(700,r.Unallocated);Assert.Equal(0,r.Allocated);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/receipts/{r.Id}/allocate",f.Allocate((rates[0].Id,500),(rates[1].Id,200.01m))));var assigned=await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{r.Id}/allocate",f.Allocate((rates[0].Id,500),(rates[1].Id,200)));Assert.Equal(700,assigned.Allocated);Assert.Equal(0,assigned.Unallocated);
        var unmatched=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(250));Assert.Equal(250,unmatched.Unallocated);Assert.Equal(0,unmatched.Allocated);await using var db=Db(f.Base.Tenant);Assert.Equal(2,await db.JournalEntries.CountAsync(j=>j.Kind==JournalKind.Receipt));
    }
    [PostgresFact] public async Task ExistingBankMovementManualMatchingDoesNotDuplicateBankAndCannotMatchTwice()
    {
        await using var f=await Setup();var accounting=$"/api/accounting/condominiums/{f.Base.Condo}";var movement=await Send<JournalDto>(f.C,accounting+"/receipts",new ReceiptInput(Guid.NewGuid(),f.Base.Period,f.Financial,new(2026,8,1),250,"Synthetic imported receipt",null));var r=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(250,recordOnly:true));Assert.Equal("Unmatched",r.Status);Assert.Null(r.BankJournalId);
        var wrong=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(249,recordOnly:true));Assert.Equal(HttpStatusCode.BadRequest,await Status(f.C,f.Path+$"/receipts/{wrong.Id}/match",new BankMatchInput(movement.Id)));var matched=await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{r.Id}/match",new BankMatchInput(movement.Id));Assert.Equal("Matched",matched.Status);var reconciled=await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{r.Id}/reconcile",new BankMatchInput(movement.Id));Assert.Equal("Reconciled",reconciled.Status);
        var another=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(250,recordOnly:true));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/receipts/{another.Id}/match",new BankMatchInput(movement.Id)));Assert.Empty(await Get<JournalDto[]>(f.C,f.Path+"/bank-movements"));var bank=Assert.Single(await Get<FinancialAccountDto[]>(f.C,accounting+"/financial-accounts"));Assert.Equal(250,bank.Balance);
    }
    [PostgresFact] public async Task ConcurrentAllocationsCannotExceedReceiptOrRateAndFailuresAreAtomic()
    {
        await using var f=await Setup();await Issue(f);var credit=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).First();var r=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(credit.Amount));var statuses=await Task.WhenAll(Status(f.C,f.Path+$"/receipts/{r.Id}/allocate",f.Allocate((credit.Id,credit.Amount))),Status(f.C,f.Path+$"/receipts/{r.Id}/allocate",f.Allocate((credit.Id,credit.Amount))));Assert.Single(statuses.Where(s=>s==HttpStatusCode.OK));Assert.Single(statuses.Where(s=>s==HttpStatusCode.Conflict));
        var other=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(100));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/receipts/{other.Id}/allocate",f.Allocate((credit.Id,1))));Assert.Equal(100,(await Get<ResidentReceiptDto[]>(f.C,f.Path+"/receipts")).Single(x=>x.Id==other.Id).Unallocated);
    }
    [PostgresFact] public async Task AllocationReversalIsImmutableAuditedAndRestoresBothResiduals()
    {
        await using var f=await Setup();await Issue(f);var credit=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).First();var r=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(200));var allocated=await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{r.Id}/allocate",f.Allocate((credit.Id,200)));var journal=Assert.Single(allocated.Allocations).JournalEntryId;var input=new ReversalInput(Guid.NewGuid(),f.Base.Period,new(2026,8,2),"Synthetic explicit correction");var reversed=await Send<ResidentReceiptDto>(f.C,f.Path+$"/allocations/{journal}/reverse",input);Assert.Equal(0,reversed.Allocated);Assert.Equal(200,reversed.Unallocated);Assert.Equal(2,reversed.Allocations.Count);Assert.Contains(reversed.Allocations,a=>a.IsReversed);await Send<ResidentReceiptDto>(f.C,f.Path+$"/allocations/{journal}/reverse",input);
        Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/allocations/{journal}/reverse",input with{RequestId=Guid.NewGuid()}));await using var db=Db(f.Base.Tenant);Assert.Single(await db.SecurityAudits.Where(a=>a.TenantId==f.Base.Tenant && a.Event=="Resident.AllocationReversed").ToListAsync());await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM \"ReceiptAllocations\" WHERE \"ReceiptId\"={r.Id}"));
    }
    [PostgresFact] public async Task OwnershipChangeKeepsOriginalDebtorAndBalancesAreReconciledToLedger()
    {
        await using var f=await Setup();await Issue(f);await using var db=Db(f.Base.Tenant);var owner=await db.OwnershipPeriods.SingleAsync(a=>a.PropertyUnitId==f.Units[0]);Assert.Equal(HttpStatusCode.NoContent,await Status(f.C,$"/api/condominiums/{f.Base.Condo}/associations/{owner.Id}/end",new EndAssociationInput(new(2026,6,30))));await Send<AssociationDto>(f.C,$"/api/condominiums/{f.Base.Condo}/units/{f.Units[0]}/associations",new AssociationInput(f.People[1],UnitPersonRole.Owner,new(2026,7,1),null,1));
        var credit=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).First(c=>c.PropertyUnitId==f.Units[0]);Assert.Equal(f.People[0],credit.DebtorId);var r=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(200,f.People[0],f.People[1]));await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{r.Id}/allocate",f.Allocate((credit.Id,200)));var balance=await Get<FinanceBalances>(f.C,f.Path+"/balances?asOf=2026-08-01");Assert.Equal(11800,balance.Residual);Assert.Equal(200,balance.Allocated);Assert.Equal(8800,balance.Positions.Sum(p=>p.Overdue));Assert.Equal(3000,balance.Positions.Sum(p=>p.NotDue));var account=await db.Accounts.SingleAsync(a=>a.CondominiumId==f.Base.Condo && a.Purpose==AccountPurpose.ResidentReceivables);Assert.Equal(balance.Residual,await db.JournalEntryLines.Where(l=>l.AccountId==account.Id).SumAsync(l=>l.Debit-l.Credit));
    }
    [PostgresFact] public async Task PlanVersionsShowDifferencesButIssuedPlanReplacementIsExplicitlyBlocked()
    {
        await using var f=await Setup();var first=await Issue(f);var next=await Send<PlanDto>(f.C,f.Path+"/plans",f.Input(10,20,30,40) with{PreviousPlanId=first.Id});Assert.All(next.Snapshot.Differences,d=>Assert.Equal(0,d.Difference));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/plans/{next.Id}/approve",new PlanApproval(Guid.NewGuid(),new(2026,1,1),next.Snapshot.Hash)));Assert.Equal(12000,(await Get<CreditDto[]>(f.C,f.Path+"/credits")).Sum(c=>c.Amount));
    }
