        await using var other=await Setup();Assert.Equal(HttpStatusCode.NotFound,await Status(other.C,f.Path+"/plans",input));Assert.Equal(HttpStatusCode.NotFound,await Status(f.C,other.Path+"/plans",input));var r=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(200));Assert.Equal(HttpStatusCode.NotFound,await Status(other.C,other.Path+$"/receipts/{r.Id}/allocate",f.Allocate((Guid.NewGuid(),1))));
        using var viewer=f.Base.Host.Browser();await SecurityTestHost.Login(viewer,await f.Base.Host.Account(f.Base.Tenant,StudioRole.Viewer),f.Base.Tenant);Assert.Equal(HttpStatusCode.Forbidden,await Status(viewer,f.Path+"/plans",input));Assert.Equal(HttpStatusCode.Forbidden,await Status(viewer,f.Path+"/receipts",f.Receipt(1)));using var anonymous=f.Base.Host.Browser();Assert.Equal(HttpStatusCode.Unauthorized,(await anonymous.GetAsync(f.Path+"/credits")).StatusCode);
