        var p1=await Send<PlanDto>(f.C,f.Path+"/plans",input);var amountInput=input with{RequestId=Guid.NewGuid(),PreviousPlanId=p1.Id,Mode=ScheduleMode.Amounts,Schedule=input.Schedule.Select((s,i)=>s with{Weight=new decimal[]{1200.01m,2399.99m,3600.01m,4799.99m}[i]}).ToArray()};var p2=await Send<PlanDto>(f.C,f.Path+"/plans",amountInput);Assert.Equal(2,p2.Version);Assert.Equal(amountInput.Schedule.Select(s=>s.Weight),p2.Snapshot.Installments.GroupBy(i=>i.Position).OrderBy(g=>g.Key).Select(g=>g.Sum(i=>i.Amount)));Assert.Empty(await Get<CreditDto[]>(f.C,f.Path+"/credits"));await Send<PlanDto>(f.C,f.Path+$"/plans/{p2.Id}/approve",new PlanApproval(Guid.NewGuid(),new(2026,1,1),p2.Snapshot.Hash));Assert.Equal(InstallmentPlanStatus.Superseded,(await Get<PlanDto[]>(f.C,f.Path+"/plans")).Single(p=>p.Id==p1.Id).Status);
