        Assert.Equal(HttpStatusCode.NotFound,await Status(f.C,path+"/plans",f.Input(100)));Assert.Equal(HttpStatusCode.NotFound,await Status(f.C,path+$"/receipts/{receipt.Id}/allocate",f.Allocate((Guid.NewGuid(),1))));
        var unit=await Send<PropertyUnitDto>(f.C,registry+"/units",new PropertyUnitInput("U",null,null,null,null,PropertyUnitKind.Apartment,null,null));await Send<AssociationDto>(f.C,registry+$"/units/{unit.Id}/associations",new AssociationInput(f.People[0],UnitPersonRole.Owner,new(2026,1,1),null,1));
        var period=await Send<AccountingPeriodDto>(f.C,registry+"/accounting-periods",new AccountingPeriodInput("E","Other synthetic period",new(2026,1,1),new(2026,12,31)));await Send<AccountingPeriodDto>(f.C,registry+$"/accounting-periods/{period.Id}/open",new{});
