        var budgetPath=$"/api/budgets/condominiums/{other.Id}";var budget=await Send<BudgetDto>(f.C,budgetPath,new BudgetInput(period.Id,"Other synthetic budget",[new(accounts.First(a=>a.Type==AccountType.Expense).Id,"Expense",100,rule.Id)]));await Send<BudgetDto>(f.C,budgetPath+$"/{budget.Id}/propose",new{});var preview=await Send<BudgetPreviewDto>(f.C,budgetPath+$"/{budget.Id}/preview",new{});await Send<BudgetDto>(f.C,budgetPath+$"/{budget.Id}/approve",new BudgetApprovalInput(preview.Hash));
