    [PostgresFact] public async Task CompetingReceiptsCannotOverpaySameInstallment()
    {
        await using var f=await Setup();await Issue(f);var credit=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).First(c=>c.PropertyUnitId==f.Units[0]);var a=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(1000));var b=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(1000));var outcomes=await Task.WhenAll(Status(f.C,f.Path+$"/receipts/{a.Id}/allocate",f.Allocate((credit.Id,1000))),Status(f.C,f.Path+$"/receipts/{b.Id}/allocate",f.Allocate((credit.Id,1000))));Assert.Single(outcomes.Where(s=>s==HttpStatusCode.OK));Assert.Single(outcomes.Where(s=>s==HttpStatusCode.Conflict));Assert.Equal(1000,(await Get<CreditDto[]>(f.C,f.Path+"/credits")).Single(c=>c.Id==credit.Id).Paid);
    }    [PostgresFact] public async Task FailedMultiRateBatchLeavesNoPartialAttributionsOrJournal()
    {
        await using var f=await Setup();await Issue(f);var rate=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).First();var receipt=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(100));Assert.Equal(HttpStatusCode.NotFound,await Status(f.C,f.Path+$"/receipts/{receipt.Id}/allocate",f.Allocate((rate.Id,20),(Guid.NewGuid(),20))));
        var result=(await Get<ResidentReceiptDto[]>(f.C,f.Path+"/receipts")).Single(r=>r.Id==receipt.Id);Assert.Empty(result.Allocations);Assert.Equal(100,result.Unallocated);Assert.Equal(0,(await Get<CreditDto[]>(f.C,f.Path+"/credits")).Sum(c=>c.Paid));await using var db=Db(f.Base.Tenant);Assert.Empty(await db.JournalEntries.Where(j=>j.CondominiumId==f.Base.Condo && j.Kind==JournalKind.ReceiptAttribution).ToListAsync());
    }}
